void preset_icum_rsa_cert_import_std(r_icumif_isd_t *p_ISD, 
    r_number_format_t key_format ,
    int modulus_size_in_bits, uint8_t *p_modulus,
    int pub_exp_size_in_bits, uint8_t *p_pub_exp )
{
    // initialize the global icum service header
    memset(p_ISD, 0, SIZE_OF_ISD_BUFFER);   // clear the ISD_BUFFER

    p_ISD->service_id     = SERVICE_03_PK_IMPORT;
    p_ISD->p_callbackfunc = 0;
    p_ISD->job_id         = 0;
    
    p_ISD->prm.PK_IMPORT.p_modulus                = p_modulus;
    p_ISD->prm.PK_IMPORT.p_pub_exp                = p_pub_exp;
    p_ISD->prm.PK_IMPORT.modulus_size_in_bits     = modulus_size_in_bits;
    p_ISD->prm.PK_IMPORT.pub_exp_size_in_bits     = pub_exp_size_in_bits;
    p_ISD->prm.PK_IMPORT.priv_exp_size_in_bits    = 0;
    p_ISD->prm.PK_IMPORT.key_format               = key_format;
    p_ISD->prm.PK_IMPORT.key_group                = KEY_GRP_RSA_PUB;
    p_ISD->prm.PK_IMPORT.key_id                   = 1;
    p_ISD->prm.PK_IMPORT.p_info                   = 0;
    p_ISD->prm.PK_IMPORT.info_size_in_bytes       = 0;

    p_ISD->prm.PK_IMPORT.p_signature              = 0;
    p_ISD->prm.PK_IMPORT.sig_format               = (r_number_format_t)0;
    p_ISD->prm.PK_IMPORT.sig_size_in_bits         = 0;
    p_ISD->prm.PK_IMPORT.sig_algo                 = SIGALGO_NONE;

    p_ISD->prm.PK_IMPORT.sig_key_group            = KEY_GRP_RSA_ROM_PUB;
    p_ISD->prm.PK_IMPORT.sig_key_id               = 0;
    p_ISD->prm.PK_IMPORT.flags.disable_on_debug   = 0;
}

