void icum_rsa_cert_import_performance(uint8_t skip_verify)
{
    r_icumif_isd_t *p_ISD = (r_icumif_isd_t *)ISD_BUFFER;

    pause_life_signal();

    preset_icum_rsa_cert_import_std( p_ISD,
                    FORMAT_BINARY_PLAIN,
                    2048, (void *)N_2048_plain,
                    8 * sizeof(E_plain), (void *)E_plain );

    p_ISD->prm.PK_IMPORT.key_id                 = 0;
    p_ISD->prm.PK_IMPORT.sig_algo               = SIGALGO_NONE;
    p_ISD->prm.PK_IMPORT.skip_verify            = 0;

    // trigger the security service
    EXEC_SERVICE_WITH_TIMESTAMP(p_ISD);

    printf("\nDone!\n");

    printf("\nPerformance Measure with 2048bits signature[pkcs#1]  (expect a success) ...\n");

    preset_icum_rsa_cert_import_std( p_ISD,
                    FORMAT_BINARY_PLAIN,
                    2048,   (void *)N_2048_plain,
                      17,   (void *)E_plain );

    p_ISD->prm.PK_IMPORT.p_signature            = sig_key2048_sha256_keyN2048_pkcs;
    p_ISD->prm.PK_IMPORT.sig_format             = FORMAT_BINARY_PLAIN;
    p_ISD->prm.PK_IMPORT.sig_size_in_bits       = 2048;
    p_ISD->prm.PK_IMPORT.sig_algo               = SIGALGO_RSA_PKCS1_V15;
    p_ISD->prm.PK_IMPORT.hash_primitive         = HASH_PRIMITIVE_SHA2_256;
    p_ISD->prm.PK_IMPORT.sig_key_group          = KEY_GRP_RSA_PUB;
    p_ISD->prm.PK_IMPORT.sig_key_id             = 0;

    p_ISD->prm.PK_IMPORT.skip_verify            = skip_verify;

    // trigger the security service
    EXEC_SERVICE_WITH_TIMESTAMP(p_ISD);

    restart_life_signal();

    printf("\nDone!\n");
}

