static void test_rsa2048_x509cert_import_setup(void)
{
    r_icumif_isd_t *p_ISD = (r_icumif_isd_t *)ISD_BUFFER;

    // initialize the global icum service header
    memset(ISD_BUFFER, 0, SIZE_OF_ISD_BUFFER);  // clear the ISD_BUFFER
    p_ISD = (r_icumif_isd_t *)ISD_BUFFER;

    printf("\nSetup x509cert_import_with_verify(RSA key pair(2048bit) import index #0)...\n\n");

    p_ISD->service_id     = SERVICE_03_PK_IMPORT;
    p_ISD->p_callbackfunc = 0;
    p_ISD->job_id         = 0;
    
    p_ISD->prm.PK_IMPORT.key_group                = KEY_GRP_RSA_PUB;
    p_ISD->prm.PK_IMPORT.key_id                   = 0;
    p_ISD->prm.PK_IMPORT.p_priv_exp               = rsa2048_x509_signkey_priv_exponent;
    p_ISD->prm.PK_IMPORT.p_pub_exp                = rsa2048_x509_signkey_pub_exponent;
    p_ISD->prm.PK_IMPORT.p_modulus                = rsa2048_x509_signkey_modulus;
    p_ISD->prm.PK_IMPORT.priv_exp_size_in_bits    = sizeof(rsa2048_x509_signkey_priv_exponent) * 8;
    p_ISD->prm.PK_IMPORT.pub_exp_size_in_bits     = sizeof(rsa2048_x509_signkey_pub_exponent) * 8;
    p_ISD->prm.PK_IMPORT.modulus_size_in_bits     = sizeof(rsa2048_x509_signkey_modulus) * 8;
    p_ISD->prm.PK_IMPORT.key_format               = FORMAT_BINARY_PLAIN;
    p_ISD->prm.PK_IMPORT.sig_algo                 = SIGALGO_NONE;
    p_ISD->prm.PK_IMPORT.flags.disable_on_debug   = 0;
    p_ISD->prm.PK_IMPORT.skip_verify              = 0;
    
    // trigger the security service
    EXEC_SERVICE_WITH_TIMESTAMP(p_ISD);
    
    printf("\nDone!\n");
}

static void test_rsa2048_x509cert_import_id_1(uint8_t skip_verify)
{
    r_icumif_isd_t *p_ISD = (r_icumif_isd_t *)ISD_BUFFER;

    // import sign key
    test_rsa2048_x509cert_import_setup();

    pause_life_signal();

    // initialize the global icum service header
    memset(ISD_BUFFER, 0, SIZE_OF_ISD_BUFFER);  // clear the ISD_BUFFER
    p_ISD = (r_icumif_isd_t *)ISD_BUFFER;

    printf("\nTest with X.509 cert import to index #1 (rsa pkcs#1 2048bit) (expect a success) ...\n");

    p_ISD->service_id     = SERVICE_03_PK_IMPORT;
    p_ISD->p_callbackfunc = 0;
    p_ISD->job_id         = 0;
    
    p_ISD->prm.PK_IMPORT.p_x509_certificate             = rsa2048_pkcs_sha256_der;
    p_ISD->prm.PK_IMPORT.x509_certificate_size_in_bytes = sizeof(rsa2048_pkcs_sha256_der);
    p_ISD->prm.PK_IMPORT.key_group                      = KEY_GRP_RSA_PUB;
    p_ISD->prm.PK_IMPORT.key_id                         = 1;
    p_ISD->prm.PK_IMPORT.sig_algo                       = SIGALGO_RSA_PKCS1_V15;
    p_ISD->prm.PK_IMPORT.hash_primitive                 = HASH_PRIMITIVE_SHA2_256;
    p_ISD->prm.PK_IMPORT.sig_key_group                  = KEY_GRP_RSA_PUB;
    p_ISD->prm.PK_IMPORT.sig_key_id                     = 0;
    p_ISD->prm.PK_IMPORT.flags.disable_on_debug         = 0;
    
    p_ISD->prm.PK_IMPORT.skip_verify                    = skip_verify;

    // trigger the security service
    EXEC_SERVICE_WITH_TIMESTAMP(p_ISD);

    restart_life_signal();

    printf("\nDone!\n");

}




