static void icum_rsa_key_x509_3072_import(uint8_t skip_verify)
{
    int i;
    
    r_icumif_isd_t  *p_ISD  = (r_icumif_isd_t *)ISD_BUFFER;
    r_icumif_service_result_t expected = SERV_OK;
    
    for(i = 1; i < 5;i++)
    {
        
        memset(p_ISD, 0, SIZE_OF_ISD_BUFFER);
    
        p_ISD->service_id     = SERVICE_03_PK_IMPORT;
        p_ISD->p_callbackfunc = 0;
        p_ISD->job_id         = 0;
    
        printf("Test icum_pk_import_RSA x509_%d\n",i);
        p_ISD->prm.PK_IMPORT.sig_key_group                  = KEY_GRP_RSA_PUB;
        p_ISD->prm.PK_IMPORT.sig_algo                       = SIGALGO_RSA_PKCS1_V15;
        p_ISD->prm.PK_IMPORT.p_info                         = 0;
        p_ISD->prm.PK_IMPORT.info_size_in_bytes             = 0;
        
        p_ISD->prm.PK_IMPORT.key_id                         = i;
        switch(i)
        {
            case 1:
                p_ISD->prm.PK_IMPORT.hash_primitive                 = HASH_PRIMITIVE_SHA1;
                p_ISD->prm.PK_IMPORT.p_x509_certificate             = subjRSA512Cert_sha1_rsa3072;
                p_ISD->prm.PK_IMPORT.x509_certificate_size_in_bytes = sizeof(subjRSA512Cert_sha1_rsa3072);
            break;
            case 2:
                p_ISD->prm.PK_IMPORT.hash_primitive                 = HASH_PRIMITIVE_SHA2_384;
                p_ISD->prm.PK_IMPORT.p_x509_certificate             = subjRSA2048Cert_sha384_rsa3072;
                p_ISD->prm.PK_IMPORT.x509_certificate_size_in_bytes = sizeof(subjRSA2048Cert_sha384_rsa3072);
            break;
            case 3:
                p_ISD->prm.PK_IMPORT.hash_primitive                 = HASH_PRIMITIVE_SHA2_512;
                p_ISD->prm.PK_IMPORT.p_x509_certificate             = subjRSA3072Cert_sha512_rsa3072;
                p_ISD->prm.PK_IMPORT.x509_certificate_size_in_bytes = sizeof(subjRSA3072Cert_sha512_rsa3072);
            break;
            case 4:
                p_ISD->prm.PK_IMPORT.hash_primitive                 = HASH_PRIMITIVE_SHA2_512;
                p_ISD->prm.PK_IMPORT.p_x509_certificate             = rootRSA3072Cert_sha512_v3;
                p_ISD->prm.PK_IMPORT.x509_certificate_size_in_bytes = sizeof(rootRSA3072Cert_sha512_v3);
            break;
        }
        p_ISD->prm.PK_IMPORT.key_group                      = KEY_GRP_RSA_PUB;
        p_ISD->prm.PK_IMPORT.flags.disable_on_debug         = 0;
        p_ISD->prm.PK_IMPORT.flags.write_protected          = 0;
        p_ISD->prm.PK_IMPORT.skip_verify                    = skip_verify;
        
        EXEC_SERVICE_WITH_TIMESTAMP(p_ISD);
        printf("----------------------------------------------------------------------------------\n");
        printf("----------------------------------------------------------------------------------\n");
        printf("service result : ");
        if(p_ISD->service_result == expected)
        {
            if(p_ISD->service_result == SERV_OK)
            {
                printf( "Expected. (PASS!)\n");
            }
            else
            {
                printf( "Expected.  %d (%s)\n", p_ISD->service_result, R_ICUMIF_GetErrorCodeName(p_ISD->service_result) );
            }
        }
        else
        {
            printf( "NOT EXPECTED !! %d (%s)\n", p_ISD->service_result, R_ICUMIF_GetErrorCodeName(p_ISD->service_result) );
        }
        printf("----------------------------------------------------------------------------------\n\n");
    }
    
}

