static void icum_rsa_priv_key_import(void)
{
    
    int n;
    
    while(1)
    {
        printf("\n\n| RSA_PRIV_KEY IMPORT tests\n");
        printf("|---------------------------------\n");
        printf("| 0  : 3072 signature_key_import \n");
        printf("| 1  : Test pk_importRSA_priv_1\n");
        printf("| 2  : Test pk_importRSA_priv_2\n");
        printf("| 3  : Test pk_importRSA_priv_3\n");
        printf("| 4  : Test pk_importRSA_priv_4\n");
        printf("| 5  : Test pk_importRSA_priv_5\n");
        printf("| 6  : Test pk_importRSA_priv_6\n");
        printf("| 7  : Test pk_importRSA_priv_7\n");
        printf("| 8  : Test pk_importRSA_priv_8\n");
        printf("| 9  : 2048 signature_key_import \n");
        printf("| 10 : Test pk_importRSA_priv_9\n");
        printf("| 11 : Test pk_importRSA_priv_10\n");
        printf("| q  : Quit\n\n");
        printf("  ?> ");
        vrun_console_get();
        if(*(char *)vrun_iobuff_readparam(0) == 'q')
        {
            n = -1;
            break;
        }
        else
        {
            sscanf(vrun_iobuff_readparam(0), "%i", &n);
        }
        
        
        switch(n)
        {
            case 0:
                icum_sig_3072_import(0);
                break;
            case 1:
                icum_RSA_priv_import1(0);
                break;
            case 2:
                icum_RSA_priv_import2(0);
                break;
            case 3:
                icum_RSA_priv_import3(0);
                break;
            case 4:
                icum_RSA_priv_import4(0);
                break;
            case 5:
                icum_RSA_priv_import5(0);
                break;
            case 6:
                icum_RSA_priv_import6(0);
                break;
            case 7:
                icum_RSA_priv_import7(0);
                break;
            case 8:
                icum_RSA_priv_import8(0);
                break;
            case 9:
                icum_sig_2048_import(0);
                break;
            case 10:
                icum_RSA_priv_import9(0);
                break;
            case 11:
                icum_RSA_priv_import10(0);
                break;
            
        }
    }
}

static void icum_rsa_key_import(uint8_t skip_verify)
{
    icum_sig_3072_import(skip_verify);
    icum_rsa_key_3027_import(skip_verify);
    icum_sig_2048_import(skip_verify);
    icum_rsa_key_2048_import(skip_verify);
    icum_x509_sig_rsa3072_import(skip_verify);
    icum_rsa_key_x509_3072_import(skip_verify);
}

static void icum_rsa_key_import_skip_verificaton(void)
{
    icum_rsa_key_import(1);
    icum_RSA_priv_import1(1);
    icum_RSA_priv_import2(1);
    icum_RSA_priv_import3(1);
    icum_RSA_priv_import4(1);
    icum_RSA_priv_import5(1);
    icum_RSA_priv_import6(1);
    icum_RSA_priv_import7(1);
    icum_RSA_priv_import8(1);
    icum_RSA_priv_import9(1);
    icum_RSA_priv_import10(1);
}

void show_submenu_for_pk_import(void)
{
    int n;
    int exit_loop = 0;

    while(!exit_loop)
    {
        printf("\n\n| ICU-M Hello! PK_IMPORT tests\n");
        printf("|---------------------------------\n");
        printf("| 6  : Test RSA key pair import with vefication\n");
        printf("| 7  : Test RSA key pair import without vefication\n");
        printf("| 9  : Test RSA_PUB Key Import\n");
        printf("| 10 : Test RSA_priv Key Import\n");
        printf("| 11 : Test RSA Key Import skip_verificaton\n");
        printf("| 12 : Test RSA_pk_import_err_test\n");
        printf("| 13 : Test RSA_pk_import_err_test skip_verificaton\n");
        printf("| 14 : Test RSA pk_import investigation10\n");
        printf("| 15 : Test RSA pk_import investigation11\n");
        printf("| q  : Quit\n\n");
        printf("  ?> ");
        vrun_console_get();
        if(*(char *)vrun_iobuff_readparam(0) == 'q')
        {
            n = -1;
            exit_loop = 1;
        }
        else
        {
            sscanf(vrun_iobuff_readparam(0), "%i", &n);
        }

        switch(n)
        {
            case 9:
                icum_rsa_key_import(0);
                break;
            case 10:
                icum_rsa_priv_key_import();
                break;
            case 11:
                icum_rsa_key_import_skip_verificaton();
                break;
            case 12:
                icum_rsa_pk_import_err_test();
                break;
            case 13 :
                icum_rsa_pk_import_skip_verify_err_test();
                break;
            case 14:
                icum_rsa_pk_import_investigation10();
                break;
            case 15:
                icum_rsa_pk_import_investigation11();
                break;
            default:
                break;
        }
    }
}
